#include <array>
#include <iostream>
#include <string>
using namespace std;

void solve(istream& in, ostream& out) {
    string alphabet, heard;
    in >> alphabet >> heard;
    array<int, 26> rank{};
    for (int i = 0; i < 26; ++i) rank[alphabet[i] - 'a'] = i;
    int repetitions = 1;
    for (int i = 1; i < static_cast<int>(heard.size()); ++i)
        if (rank[heard[i] - 'a'] <= rank[heard[i - 1] - 'a'])
            ++repetitions;
    out << repetitions << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
