#include <algorithm>
#include <iostream>
using namespace std;

void solve(istream& in, ostream& out) {
    int n, odd = 0;
    in >> n;
    for (int i = 0, id; i < n; ++i) {
        in >> id;
        odd += id % 2;
    }
    int even = n - odd;
    for (int groups = n; groups >= 1; --groups) {
        int oddGroups = groups / 2;
        int evenGroups = (groups + 1) / 2;
        int oddNeeded = oddGroups + 2 * max(0, evenGroups - even);
        if (odd >= oddNeeded && (odd - oddGroups) % 2 == 0) {
            out << groups << '\n';
            return;
        }
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
