#include <algorithm>
#include <functional>
#include <iostream>
#include <vector>
using namespace std;

void solve(istream& in, ostream& out) {
    int n;
    in >> n;
    vector<int> cows(n), stalls(n);
    for (int& height : cows) in >> height;
    for (int& capacity : stalls) in >> capacity;
    sort(cows.begin(), cows.end(), greater<int>());
    long long ways = 1;
    for (int i = 0; i < n; ++i) {
        int eligible = 0;
        for (int capacity : stalls) eligible += capacity >= cows[i];
        int choices = eligible - i;
        if (choices <= 0) {
            ways = 0;
            break;
        }
        ways *= choices;
    }
    out << ways << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
